import { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { } from '@/primitives';
import { } from '@/text';

/**
 * @param {Object} config
 * @param {Object} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  // Root container
  const root = new Group();

  // Apply placement (position, rotation, scale) – the adapter will later apply scenePosition,
  // but we still set the explicit values here to keep them local for animations.
  const pos = config.position ?? { x: 0, y: 0, z: 0 };
  root.position.set(pos.x ?? 0, pos.y ?? 0, pos.z ?? 0);
  const rot = config.rotation ?? { x: 0, y: 0, z: 0 };
  root.rotation.set(rot.x ?? 0, rot.y ?? 0, rot.z ?? 0);
  const scl = config.scale ?? { x: 1, y: 1, z: 1 };
  root.scale.set(scl.x ?? 1, scl.y ?? 1, scl.z ?? 1);

  // Geometry & material
  const geometry = new PlaneGeometry(1, 1);
  const material = new MeshBasicNodeMaterial({ color: 0xffffff, map: null });
  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Load texture asynchronously – keep function synchronous
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Preserve original Y for hover animation
  const originalY = root.position.y;

  // GSAP timeline for hover rise‑in effect (subtle 0.15 units)
  const hoverTimeline = gsap.timeline({ paused: true });
  hoverTimeline.to(
    root.position,
    {
      y: originalY + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    }
  );

  // Handlers registry
  const handlers = {};

  // Hover enter / leave
  handlers.hoverEnter = () => {
    hoverTimeline.play(0);
  };
  handlers.hoverLeave = () => {
    hoverTimeline.reverse(0);
  };

  // Click emit
  handlers.click = () => {
    ctx.emit('hub-pricing.select', {});
  };

  // Attach handlers to userData as required
  root.userData.handlers = {
    hoverEnter: handlers.hoverEnter,
    hoverLeave: handlers.hoverLeave,
    click: handlers.click,
  };

  // Cleanup routine
  root.userData.cleanup = () => {
    // Dispose geometry and material
    geometry.dispose();
    if (material.map) material.map.dispose();
    material.dispose();

    // Kill GSAP timeline
    hoverTimeline.kill();

    // Remove references
    root.traverse((obj) => {
      obj.userData.handlers = undefined;
    });
  };

  // Keep reference for external cleanup if needed
  root.userData._internal = {
    hoverTimeline,
  };

  return root;
}
